module rec CloudflareAgents

open System
open Fable.Core
open Fable.Core.JS
open Fable.Core.JsInterop

module rec Agents =
    module rec AgentToolChildAdapter =
        module rec GetAgentToolChunks =
            type Options =
                abstract afterSequence: option<float> with get, set

        module rec StartAgentToolRun =
            type Options =
                abstract signal: option<AbortSignal> with get, set
                abstract runId: string with get, set

        module rec TailAgentToolRun =
            type Options =
                abstract signal: option<AbortSignal> with get, set
                abstract afterSequence: option<float> with get, set

        type StartAgentToolRun =
            abstract completedAt: option<float> with get, set
            abstract startedAt: float with get, set
            abstract error: option<string> with get, set
            abstract summary: option<string> with get, set
            abstract output: option<'Output> with get, set
            abstract streamId: option<string> with get, set
            abstract requestId: option<string> with get, set
            abstract status: StartAgentToolRun.Status with get, set
            abstract runId: string with get, set

        type GetAgentToolChunks =
            abstract body: string with get, set
            abstract sequence: float with get, set

    module rec AgentToolEventState =
        module rec UnboundRuns =
            type SubAgent =
                abstract name: string with get, set
                abstract agent: string with get, set

            [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
            type Status =
                | [<CompiledName("running")>] Running
                | [<CompiledName("completed")>] Completed
                | [<CompiledName("error")>] Error
                | [<CompiledName("aborted")>] Aborted
                | [<CompiledName("interrupted")>] Interrupted

            type Display =
                abstract icon: option<string> with get, set
                abstract name: option<string> with get, set
                abstract Item: key: string -> option<AgentContext>

        type UnboundRuns =
            abstract subAgent: UnboundRuns.SubAgent with get, set
            abstract error: option<string> with get, set
            abstract summary: option<string> with get, set

            abstract parts:
