                     >
                 > with get, set

            abstract status: UnboundRuns.Status with get, set
            abstract display: option<``.``.AgentToolTypesDSteYkkSJs.AgentToolDisplayMetadata> with get, set
            abstract order: float with get, set
            abstract inputPreview: option<obj> with get, set
            abstract parentToolCallId: option<string> with get, set
            abstract agentType: string with get, set
            abstract runId: string with get, set

        type Vocabulary =
            abstract Item: key: string -> option<AgentContext>

    module rec AgentToolRunInspection =
        [<RequireQualifiedAccess; StringEnum(CaseRules.None)>]
        type Status =
            | [<CompiledName("error")>] Error
            | [<CompiledName("completed")>] Completed
            | [<CompiledName("aborted")>] Aborted
            | [<CompiledName("running")>] Running
            | [<CompiledName("starting")>] Starting

